'use strict';
const el=id=>document.getElementById(id);let token='',scope=null,report=null,active=null,desired=null,epoch=0,revealed=false,busy=false,uncertain=false,progressTimer=null,recoverable=null;
const players=new Map(),urls=new Set();
function say(text,kind=''){const s=el('status');s.textContent=text;s.className=kind;}
function fail(error){finishProgress();say(error.message||String(error),'error');}
function finishProgress(){if(progressTimer!==null){clearInterval(progressTimer);progressTimer=null;}}
// While a long step runs, the server still answers /state with what it is doing (phase, idea n of 3), so progress is real, not a guess.
function startProgress(label){finishProgress();const started=Date.now();let detail='',polling=false;const update=()=>{say(label+(detail?' — '+detail:'')+' · '+Math.floor((Date.now()-started)/1000)+' s. Nothing plays automatically.','working');};update();
 progressTimer=setInterval(async()=>{update();if(polling)return;polling=true;try{const snap=await (await request('/api/preset-variations/state',{},4000)).json();const p=snap.progress;if(snap.busy&&p)detail=p.phase+(p.variation?' (idea '+p.variation+' of '+p.of+')':'');}catch{}finally{polling=false;}},1000);}
function retainedReply(snapshot){const prepared=snapshot.preparedRequest;return snapshot.lastFailure?.canFinishWithRetainedReply&&prepared?.response?.reply?{sessionId:snapshot.sessionId,requestId:prepared.id,reply:prepared.response.reply,provenance:'fresh-provider'}:null;}
async function inspectFailure(){try{const snapshot=await jsonResponse(await request('/api/preset-variations/state'));recoverable=retainedReply(snapshot);uncertain=!!recoverable;trace(snapshot.preparedRequest,'The exact engineer reply and its usage are retained in memory. Finishing a connection-interrupted render uses them and does not call the engineer again.');if(recoverable)say('The engineer replied, but the Mac Studio connection failed before the three sounds were finished: '+snapshot.lastFailure.error+' Your starting sound is unchanged. When the Studio is back, press “Finish these variations” — it reuses that same reply, with no new engineer call.','error');}catch{}controls();}
async function resumeRendering(){if(busy||!recoverable)return;busy=true;controls();stop();startProgress('Finishing with the retained engineer reply on the Mac Studio (no new engineer call)');try{await jsonResponse(await post('reply',recoverable));finishProgress();recoverable=null;uncertain=false;await refresh();}catch(error){fail(error);await inspectFailure();}finally{finishProgress();busy=false;controls();}}
function stop(){epoch++;desired=null;for(const audio of players.values()){audio.pause();audio.currentTime=0;}active=null;}
function release(){finishProgress();stop();players.clear();for(const url of urls)URL.revokeObjectURL(url);urls.clear();}
async function jsonResponse(response){const value=await response.json();if(!response.ok)throw Error(value.error||'Comparison request failed.');return value;}
async function request(path,options={},timeoutMs=20000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeoutMs);try{return await fetch(path,{...options,signal:controller.signal});}catch(error){if(controller.signal.aborted)throw Error('Scrunch did not respond in time. Refresh to check the current comparison; no request will be retried automatically.');throw error;}finally{clearTimeout(timer);}}
async function post(action,body={}){return request('/api/preset-variations/'+action,{method:'POST',headers:{'Content-Type':'application/json','X-Scrunch-Token':token},body:JSON.stringify({...scope,...body})},['generate','reply','select-upload','branch'].includes(action)?300000:action==='audio'?60000:20000);}
function controls(){for(const id of ['load','clear','refresh','restart'])el(id).disabled=busy;el('generate').disabled=busy||uncertain||!scope;el('generate').textContent=busy?'Working…':'Create three variations';el('resumeRender').hidden=!recoverable;el('resumeRender').disabled=busy;el('startingPlay').disabled=busy;el('startingPlay').hidden=!scope||!!report;el('startingDownload').disabled=busy;el('startingDownload').hidden=!scope;el('empty').hidden=!!scope;for(const card of el('takes').children)for(const child of card.children||[])if(child.tagName==='BUTTON')child.disabled=busy;}
function trace(evidence,basis){el('trace').hidden=!evidence;el('modelBasis').textContent=basis||'';el('transcript').textContent=evidence?JSON.stringify(evidence,null,2):'';}
async function file64(file,maximum,label){if(!file||file.size===0||file.size>maximum)throw Error('Choose '+label+' within the stated file limit.');const bytes=new Uint8Array(await file.arrayBuffer());let text='';for(let i=0;i<bytes.length;i+=32768)text+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(text);}
async function load(){if(busy)return;busy=true;controls();stop();try{const preset=el('presetFile').files?.[0],midi=el('midiFile').files?.[0];const body={presetName:preset?.name,presetBase64:await file64(preset,8*1024*1024,'a Serum preset up to 8 MB'),midiBase64:await file64(midi,256*1024,'a MIDI phrase up to 256 KB')};startProgress('Loading your preset and checking the MIDI');await jsonResponse(await post('select-upload',body));finishProgress();uncertain=false;await refresh();el('presetFile').value='';el('midiFile').value='';}catch(error){fail(error);}finally{finishProgress();busy=false;controls();}}
async function generate(){if(busy||uncertain||!scope)return;const words=el('direction').value.trim();if(!words){el('status').textContent='Describe the characters you want to explore.';return;}busy=true;controls();stop();try{const prepared=await jsonResponse(await post('request',{words}));trace(prepared,'Prepared request; no provider reply yet.');startProgress('Creating your variations');await jsonResponse(await post('generate',{requestId:prepared.id}));finishProgress();await refresh();}catch(error){fail(error);await inspectFailure();}finally{finishProgress();busy=false;controls();}}
async function develop(name){if(busy)return;busy=true;controls();stop();try{const i=report.variants.findIndex(v=>v.name===name),words=el('verdict').value.trim()||'Develop Take '+String.fromCharCode(65+i)+' from this comparison.';await jsonResponse(await post('choose',{name,words}));startProgress('Making your chosen take the new starting point');await jsonResponse(await post('branch',{name}));finishProgress();await refresh();say('Your chosen variation is the new starting point. Download it any time, or describe the next round.');}catch(error){fail(error);}finally{finishProgress();busy=false;controls();}}
async function choose(name){if(busy)return;try{stop();const label=name==='original'?'original':name==='neither'?'neither':'Take '+String.fromCharCode(65+report.variants.findIndex(v=>v.name===name));const words=el('verdict').value.trim()||'Selected '+label+' in the comparison.';await jsonResponse(await post('choose',{name,words}));el('status').textContent='Your choice is recorded: '+label+'. Your original preset is unchanged.';}catch(error){el('status').textContent=error.message;}}
async function play(name){if(busy)return;const position=active?players.get(active)?.currentTime||0:0;const ticket=++epoch;desired=name;for(const audio of players.values())audio.pause();active=null;try{
 let audio=players.get(name);if(!audio){const response=await post('audio',{name});if(!response.ok){await jsonResponse(response);return;}const blob=await response.blob();if(ticket!==epoch)return;const url=URL.createObjectURL(blob);urls.add(url);audio=new Audio(url);players.set(name,audio);audio.onended=()=>{if(active===name){active=null;el('status').textContent='Passage ended.';}};}
 if(ticket!==epoch)return;audio.volume=Number(el('level').value);audio.currentTime=position;await audio.play();if(ticket!==epoch){if(desired!==name||players.get(name)!==audio)audio.pause();return;}active=name;el('status').textContent='Playing '+(name==='original'?'original':revealed?name:'selected take')+'.';
 }catch(error){if(ticket===epoch)el('status').textContent=error.message;}}
async function downloadStarting(){try{const response=await post('source-preset');if(!response.ok){await jsonResponse(response);return;}const url=URL.createObjectURL(await response.blob());urls.add(url);const link=document.createElement('a');link.href=url;link.download=el('source').textContent.split(' / ').pop().replace(/[^a-zA-Z0-9 _-]/g,'_')+'.SerumPreset';link.click();setTimeout(()=>{URL.revokeObjectURL(url);urls.delete(url);},1000);say('Starting preset downloaded to your Downloads folder.');}catch(error){fail(error);}}
async function download(name){try{const response=await post('preset',{name});if(!response.ok){await jsonResponse(response);return;}const url=URL.createObjectURL(await response.blob());urls.add(url);const link=document.createElement('a');link.href=url;link.download=name.replace(/[^a-zA-Z0-9 _-]/g,'_')+'.SerumPreset';link.click();setTimeout(()=>{URL.revokeObjectURL(url);urls.delete(url);},1000);}catch(error){el('status').textContent=error.message;}}
function draw(){el('takes').replaceChildren();report.variants.forEach((row,i)=>{const card=document.createElement('article');card.className='take';const title=document.createElement('h3');title.textContent='Take '+String.fromCharCode(65+i);const idea=document.createElement('p');idea.textContent=revealed?row.idea:'Listen first. Reveal the musical idea when you want.';card.append(title,idea);for(const [label,handler,cls] of [['Play',()=>play(row.name),''],['Choose this character',()=>choose(row.name),'choose'],['Develop this one',()=>develop(row.name),'develop'],['Download preset',()=>download(row.name),'']]){const button=document.createElement('button');button.textContent=label;button.className=cls;button.onclick=handler;card.append(button);}el('takes').append(card);});controls();}
function noteRestart(snapshot){let seen=null,had=false;try{seen=localStorage.getItem('scrunchPresetBoot');had=localStorage.getItem('scrunchPresetHadSession')==='1';}catch{}
 const banner=el('restarted');if(seen&&seen!==snapshot.bootId&&had){banner.hidden=false;banner.textContent='Scrunch was restarted at '+new Date(snapshot.serviceStarted*1000).toLocaleTimeString()+'. Your previous comparison, conversation and any preset you had not downloaded were cleared — they are only ever kept in memory, never saved. Your preset and MIDI files on disk are untouched. Load them again to continue.';}
 try{localStorage.setItem('scrunchPresetBoot',snapshot.bootId);localStorage.setItem('scrunchPresetHadSession',snapshot.sessionId?'1':'0');if(snapshot.sessionId)banner.hidden=true;}catch{}}
async function refresh(){release();scope=null;report=null;el('comparison').hidden=true;el('empty').hidden=false;el('refresh').disabled=true;try{
 const state=await jsonResponse(await request('/api/state'));token=state.token;
 let snapshot=await jsonResponse(await request('/api/preset-variations/state'));
 if(snapshot.busy){say('Scrunch is still working: '+(snapshot.progress?.phase||'busy')+'. Refresh when it finishes.','working');return;}
 noteRestart(snapshot);recoverable=retainedReply(snapshot);uncertain=!!recoverable;scope=snapshot.sessionId?{sessionId:snapshot.sessionId}:null;el('setup').open=!scope;trace(snapshot.preparedRequest,snapshot.preparedRequest?'Prepared input and any captured response; no automatic retry.':'');el('restart').hidden=!snapshot.canReturnToFavourite;el('source').textContent=snapshot.sourcePreset||'No comparison loaded';
 if(!snapshot.report){el('direction').value=snapshot.preparedRequest?.request?.input?.producer||el('direction').value;if(snapshot.lastFailure){recoverable=retainedReply(snapshot);say((recoverable?'Not finished — the Mac Studio connection failed after the engineer replied: ':'The last attempt failed: ')+snapshot.lastFailure.error+(recoverable?' Press “Finish these variations” to use that same reply (no new engineer call).':' Your starting sound is unchanged.'),'error');return;}
 if(snapshot.preparedRequest?.response?.error){say('No new sounds were created: '+snapshot.preparedRequest.response.error,'error');return;}
 say(snapshot.preparedRequest?.attempted?'The last request was attempted. Its captured response is available below.':scope?'Starting sound ready. Play it, then describe the next variations.':'Choose your favourite preset and MIDI to start.');return;}
 report=snapshot.report;el('direction').value=snapshot.preparedRequest?.request?.input?.producer||report.modelEvidence?.request?.input?.producer||el('direction').value;scope={sessionId:snapshot.sessionId,batchId:report.id};const comparison=await jsonResponse(await post('comparison'));
 el('levelNote').textContent='All four clips share '+comparison.targetLUFS.toFixed(1)+' LUFS and at least '+Math.abs(comparison.peakCeilingDbTP).toFixed(0)+' dB of true-peak headroom. Switching keeps the same position.';
 el('verification').textContent=JSON.stringify(report.variants.map(v=>({name:v.name,controls:v.controls,reloadControlsVerified:v.reloadControlsVerified,reloadAudioBitIdentical:v.reloadAudioBitIdentical,observation:v.difference.observation})),null,2);
 const evidence=snapshot.preparedRequest||report.modelEvidence;trace(evidence,snapshot.preparedRequest?'Last prepared request and captured response; comparison below may belong to an earlier successful round.':evidence?'Transcript label: '+(evidence.provenance||evidence.basis||'caller supplied')+'. '+(evidence.verificationBasis||'This label is not independent proof of a fresh model call.'):'No model transcript was supplied.');
 revealed=false;draw();el('comparison').hidden=false;el('empty').hidden=true;
 if(snapshot.lastFailure)say('The comparison below is the previous round. The latest attempt failed: '+snapshot.lastFailure.error+(recoverable?' Press “Finish these variations” to use the retained reply.':''),'error');
 else if(snapshot.preparedRequest?.response?.error)say('No new sounds were created: '+snapshot.preparedRequest.response.error+' The comparison below is the previous round.','error');
 else say(snapshot.executionComputer==='Mac Studio'?'Three variations ready. Rendered on the Mac Studio; Play listens here on your laptop.':'Ready. Nothing plays until you press Play.');
 }catch(error){fail(error);}finally{controls();}}
el('restart').onclick=async()=>{if(busy)return;busy=true;controls();try{stop();await jsonResponse(await post('restart-favourite'));await refresh();}catch(error){fail(error);}finally{busy=false;controls();}};el('load').onclick=load;el('generate').onclick=generate;el('refresh').onclick=refresh;el('original').onclick=()=>play('original');el('startingPlay').onclick=()=>play('original');el('startingDownload').onclick=downloadStarting;el('resumeRender').onclick=resumeRendering;el('stop').onclick=()=>{stop();el('status').textContent='Stopped.';};el('reveal').onclick=()=>{revealed=!revealed;draw();};el('keepOriginal').onclick=()=>choose('original');el('neither').onclick=()=>choose('neither');el('level').oninput=()=>{for(const audio of players.values())audio.volume=Number(el('level').value);};el('clear').onclick=async()=>{if(busy)return;try{release();await jsonResponse(await post('clear'));await refresh();}catch(error){el('status').textContent=error.message;}};window.addEventListener('pagehide',release);refresh();
